console.log(`Bootstrap Basic-to-Medium question pool size: ${bsPool.length}`);

const structuredQuestions = bsPool.map((q, idx) => ({
  id: `bootstrap_${idx + 1}`,
  category: "Bootstrap",
  topic: idx < 25 ? "Bootstrap 5 Basics, Containers & Breakpoints" : (idx < 50 ? "12-Column Grid System & Layout" : (idx < 75 ? "Colors, Typography & Utilities" : "Components, Cards & Forms")),
  difficulty: idx < 50 ? "Basic" : "Medium",
  question: q.q,
  options: q.opts,
  correctAnswer: q.ans,
  explanation: q.exp
}));

const outPath = path.join(__dirname, '..', 'data', 'questions', 'bootstrap.json');
fs.writeFileSync(outPath, JSON.stringify(structuredQuestions, null, 2), 'utf8');
console.log(`Saved ${structuredQuestions.length} Bootstrap questions to ${outPath}`);
